"""Brute-force solvers for Vertex Cover and Independent Set (small n)."""

from __future__ import annotations

from itertools import combinations


def _has_vertex_cover(n, edges, k):
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for chosen in combinations(range(n), size):
            cover = set(chosen)
            if all(u in cover or v in cover for u, v in edges):
                return True
    return False


def _has_independent_set(n, edges, k):
    if k <= 0:
        return True
    if k > n:
        return False
    for size in range(k, n + 1):
        for chosen in combinations(range(n), size):
            s = set(chosen)
            if all(not (u in s and v in s) for u, v in edges):
                return True
    return False


def solve_vertex_cover(instance):
    return _has_vertex_cover(instance["n"], instance["edges"], instance["k"])


def solve_independent_set(instance):
    return _has_independent_set(instance["n"], instance["edges"], instance["k"])
